"""Request handling for the API.

Every request must pass signature verification before its payload is processed.
"""


def _validate_request(data, signature):
    """Raise ``PermissionError`` unless the request has a valid signature."""
    if not verify_signature(data, signature):
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate the request and process its payload."""
    _validate_request(data, signature)
    return process(data)

